public class AbstractCommandLineRunner_doRun_TriageGen1Test {

    // Mocking the abstract class to test the protected method
    private TestRunner runner;

    @Mock private Compiler mockCompiler;
    @Mock private CompilerOptions mockOptions;
    @Mock private CommandLineConfig mockConfig;
    @Mock private Result mockResult;

    // Concrete implementation for testing purposes
    private static class TestRunner extends AbstractCommandLineRunner<Compiler, CompilerOptions> {
        private final CommandLineConfig config;
        private final Charset inputCharset;
        private java.io.Writer out;

        protected TestRunner(CommandLineConfig config, Charset inputCharset) {
            this.config = config;
            this.inputCharset = inputCharset;
        }

        @Override
        protected Compiler createCompiler() { return mockCompiler; }

        @Override
        protected CompilerOptions createOptions() { return mockOptions; }

        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }

        @Override
        protected void setRunOptions(CompilerOptions options) throws FlagUsageException, IOException {}

        @Override
        protected List<JSSourceFile> createExterns() throws FlagUsageException, IOException {
            return Collections.emptyList();
        }

        @Override
        protected List<JSSourceFile> createSourceInputs(List<String> jsFiles) throws FlagUsageException, IOException {
            return Collections.emptyList();
        }

        @Override
        protected JSModule[] createJsModules(List<String> moduleSpecs, List<String> jsFiles) throws FlagUsageException, IOException {
            return new JSModule[0];
        }

        @Override
        protected int processResults(Result result, JSModule[] modules, CompilerOptions options) {
            return 0;
        }

        // Helper to simulate toWriter
        protected java.io.Writer toWriter(String fileName, String charsetName) throws IOException {
            this.out = new StringWriter();
            return this.out;
        }

        // Expose protected field for testing
        public void setOut(java.io.Writer out) { this.out = out; }
        public Charset getInputCharset() { return inputCharset; }
    }

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // Setup default config behavior
        when(mockConfig.loggingLevel).thenReturn("INFO");
        when(mockConfig.js).thenReturn(new ArrayList<>());
        when(mockConfig.module).thenReturn(new ArrayList<>());
        when(mockOptions.jsOutputFile).thenReturn("");

        // Setup compiler behavior
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);
        when(mockCompiler.compile(any(), any(JSSourceFile[].class), any())).thenReturn(mockResult);
    }

    @Test
    public void testDoRun_ModulesPath_UTF8Input() throws Exception {
        // Arrange
        List<String> moduleSpecs = Collections.singletonList("module.js");
        List<String> jsFiles = Collections.singletonList("file.js");

        when(mockConfig.module).thenReturn(moduleSpecs);
        when(mockConfig.js).thenReturn(jsFiles);
        when(mockOptions.jsOutputFile).thenReturn("output.js");

        TestRunner runner = spy(new TestRunner(mockConfig, StandardCharsets.UTF_8));
        doReturn(mockOptions).when(runner).createOptions();
        doReturn(mockCompiler).when(runner).createCompiler();
        doReturn(new StringWriter()).when(runner).toWriter(any(), any());

        when(mockCompiler.compile(any(), any(JSModule[].class), any())).thenReturn(mockResult);
        when(runner.processResults(any(), any(), any())).thenReturn(0);

        // Act
        int result = runner.doRun();

        // Assert
        assertEquals(0, result);
        // Verify UTF-8 input triggers US_ASCII output per logic
        assertEquals(StandardCharsets.US_ASCII, mockOptions.outputCharset);
    }

    @Test
    public void testDoRun_NoModulesPath_OtherCharset() throws Exception {
        // Arrange
        Charset customCharset = Charset.forName("ISO-8859-1");
        when(mockConfig.module).thenReturn(new ArrayList<>());
        when(mockConfig.js).thenReturn(Collections.singletonList("file.js"));
        when(mockOptions.jsOutputFile).thenReturn("");

        TestRunner runner = spy(new TestRunner(mockConfig, customCharset));
        doReturn(mockOptions).when(runner).createOptions();
        doReturn(mockCompiler).when(runner).createCompiler();

        when(mockCompiler.compile(any(), any(JSSourceFile[].class), any())).thenReturn(mockResult);
        when(runner.processResults(any(), any(), any())).thenReturn(1);

        // Act
        int result = runner.doRun();

        // Assert
        assertEquals(1, result);
        assertEquals(customCharset, mockOptions.outputCharset);
    }

    @Test
    public void testDoRun_WithFileOutput() throws Exception {
        // Arrange
        when(mockConfig.module).thenReturn(new ArrayList<>());
        when(mockConfig.js).thenReturn(Collections.singletonList("file.js"));
        when(mockOptions.jsOutputFile).thenReturn("out.js");

        TestRunner runner = spy(new TestRunner(mockConfig, StandardCharsets.UTF_8));
        doReturn(mockOptions).when(runner).createOptions();
        doReturn(mockCompiler).when(runner).createCompiler();

        StringWriter writer = new StringWriter();
        doReturn(writer).when(runner).toWriter(any(), any());

        when(mockCompiler.compile(any(), any(JSSourceFile[].class), any())).thenReturn(mockResult);
        when(runner.processResults(any(), any(), any())).thenReturn(0);

        // Act
        int result = runner.doRun();

        // Assert
        assertEquals(0, result);
        // Verify writer is closed (implicitly via the logic in doRun)
        // In a real scenario, we'd check if writer.close() was called.
    }
}
